/**
 * schemas/quizSchema.ts
 *
 * Defines the schema for structured quiz outputs.
 *
 * Responsibilities:
 * - Enforce consistency and completeness in quizzes.
 * - Validate JSON outputs generated by the OpenAI API against this schema.
 *
 * Dependencies:
 * - Zod for schema definition and validation.
 * - Used in `aiService.ts` for validating responses.
 */

import { z } from "zod";

export const QuizSchema = z.object({
  id: z.string(), // Unique identifier for the quiz.
  title: z.string(), // Title of the quiz.
  questions: z.array(
    z.object({
      id: z.string(), // Unique identifier for each question.
      question: z.string(), // The question text.
      options: z.array(z.string()), // Multiple-choice options.
      correctAnswer: z.array(z.string()), // Array of correct answers.
    })
  ),
});
